194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
197	        HttpHeaders headers = new HttpHeaders();
198	        String idempotencyKey = currentIdempotencyKey();
199	        if (idempotencyKey != null) {
200	            Integer existingId = idempotentCreates.get(idempotencyKey);
201	            if (existingId != null) {
202	                Owner existing = this.clinicService.findOwnerById(existingId);
203	                if (existing != null) {
204	                    // Repeat of a create already performed under this key: return the original
205	                    // owner with 200 instead of creating a duplicate.
206	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
207	                }
208	            }
209	        }
210	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
211	        LocalDate suppliedDate = owner.getRegistrationDate();
212	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
213	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
214	        }
215	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
216	        LocalDate registrationDate = toBusinessDay(effectiveDate);
217	        owner.setRegistrationDate(registrationDate);
218	        long createdToday = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        if (createdToday >= 100) {
222	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
223	        }
224	        owner.setBulkSignupWarning(createdToday > 80);
225	        if (!applyAddress(owner)) {
226	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
227	        }
228	        String telephone = toE164(owner.getTelephone());
229	        if (telephone == null) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        owner.setTelephone(telephone);
233	        if (owner.getEmail() != null) {
234	            String email = normalizeEmail(owner.getEmail());
235	            if (!EMAIL_PATTERN.matcher(email).matches()) {
236	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
237	            }
238	            if (isDisposableEmailDomain(email)) {
239	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
240	            }
241	            owner.setEmail(email);
242	        }
243	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
244	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
245	        }
246	        String cityKey = householdKey(owner.getCity());
247	        long cityCount = this.clinicService.findAllOwners().stream()
248	            .filter(existing -> existing.getCity() != null
249	                && cityKey.equals(householdKey(existing.getCity())))
250	            .count();
251	        if (cityCount >= 50) {
252	            return new ResponseEntity<>(HttpStatus.CONFLICT);
253	        }
254	        // Approaching-capacity warning: the city already holds 40-49 owners, just short of the
255	        // hard limit of 50. The 50+ rejection above still applies unchanged.
256	        owner.setCapacityWarning(cityCount >= 40 && cityCount < 50);
257	        // The household is keyed on (normalized last name, postcode): every owner derives the same
258	        // deterministic householdId from those two fields, so owners sharing them are the same
259	        // household. This computed id is what duplicate detection and the household size below key off.
260	        String householdId = householdId(owner);
261	        owner.setHouseholdId(householdId);
262	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
263	            .filter(existing -> !existing.getDeleted())
264	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
265	            .toList();
266	        owner.setHouseholdSize(householdMembers.size() + 1);
267	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
268	        // Duplicate detection is now the single identityKey (below): the separate household-duplicate
269	        // 409 block from the computed householdId no longer applies. Two owners sharing a last name and
270	        // postcode but with different telephones therefore have different identity keys and are admitted
271	        // as a soft match rather than rejected. The householdId and householdSize computed above still
272	        // drive household sizing and the level ceiling below.
273	        // Level ceiling: an owner admitted into an already-populated household without declaring
274	        // membership has its membership level capped at one above the household's current maximum, so
275	        // an undeclared newcomer can never outrank the household it joined. Declared members and
276	        // household founders are left uncapped. With no existing household member no cap applies.
277	        if (!householdMembers.isEmpty() && !sharesHousehold) {
278	            int maxHouseholdLevel = householdMembers.stream()
279	                .mapToInt(Owner::getMembershipLevel)
280	                .max()
281	                .orElse(0);
282	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
283	        }
284	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
285	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
286	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
287	        // telephone is part of the key, two household members with different telephones are allowed.
288	        // This still catches a full identity repeat even when it declares sharesHousehold.
289	        String identityKey = owner.getIdentityKey();
290	        boolean identityInUse = this.clinicService.findAllOwners().stream()
291	            .filter(existing -> !existing.getDeleted())
292	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
293	        if (identityInUse) {
294	            return new ResponseEntity<>(HttpStatus.CONFLICT);
295	        }
296	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
297	        // duplicate. Any other owner whose identityKey differs from an existing owner's but that shares
298	        // that owner's Soundex(last name) and postcode is flagged as a possible duplicate of the
299	        // earliest such owner. A full identity match would already have been rejected as a 409 above,
300	        // so every existing owner reaching here necessarily has a different identityKey.
301	        if (sharesHousehold) {
302	            owner.setPossibleDuplicate(false);
303	        } else {
304	            String softDuplicateLastNameSoundex = Owner.soundex(owner.getLastName());
305	            String softDuplicatePostcode = owner.getPostcode();
306	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
307	                : this.clinicService.findAllOwners().stream()
308	                    .filter(existing -> !existing.getDeleted())
309	                    .filter(existing -> softDuplicateLastNameSoundex.equals(Owner.soundex(existing.getLastName())))
310	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
311	                    .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
312	                    .min(Comparator.comparing(Owner::getId))
313	                    .orElse(null);
314	            if (possibleDuplicate != null) {
315	                owner.setPossibleDuplicate(true);
316	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
317	            } else {
318	                owner.setPossibleDuplicate(false);
319	            }
320	        }
321	        owner.setMemberId(memberId(owner));
322	        String firstNameKey = householdKey(owner.getFirstName());
323	        String namesakeLastNameKey = householdKey(owner.getLastName());
324	        long namesakeCount = this.clinicService.findAllOwners().stream()
325	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
326	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
327	            .count();
328	        owner.setNamesakeCount((int) namesakeCount);
329	        this.clinicService.saveOwner(owner);
330	        if (idempotencyKey != null) {
331	            idempotentCreates.put(idempotencyKey, owner.getId());
332	        }
333	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
334	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
335	            owner.getMembershipLevel());
336	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
337	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
338	        AUDIT.info("{}", event.toJson());
339	        // Enqueue a welcome notification for the freshly created owner, carrying the owner id and
340	        // the member id so downstream delivery can address and personalize it.
341	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
342	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
343	        headers.setLocation(UriComponentsBuilder.newInstance()
344	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
345	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
346	    }
