348	    /**
349	     * Validates an owner's postcode against the region derived from its city. The postcode is
350	     * optional: a {@code null} value is always accepted. When present it must fall within the
351	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
352	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
353	     * The 4-digit syntax itself is enforced upstream by bean validation.
354	     *
355	     * @param postcode the owner's postcode (may be {@code null})
356	     * @param locality the region derived from the owner's city
357	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
358	     *         within the region's range; {@code false} when it is out of range
359	     */
360	    /**
361	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
362	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
363	     *
364	     * @param city the owner's city (may be {@code null})
365	     * @return the canonical region, or {@code "UNKNOWN"}
366	     */
367	    /**
368	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
369	     * header is absent, blank, or no servlet request is bound to the current thread.
370	     *
371	     * @return the idempotency key, or {@code null}
372	     */
373	    private String currentIdempotencyKey() {
374	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
375	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
376	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
377	            if (key != null && !key.isBlank()) {
378	                return key.trim();
379	            }
380	        }
381	        return null;
382	    }
