391	    private boolean isPostcodeValidForCity(String postcode, String locality) {
392	        if (postcode == null) {
393	            return true;
394	        }
395	        int[] range = REGION_POSTCODES.get(locality);
396	        if (range == null) {
397	            return true;
398	        }
399	        int value = Integer.parseInt(postcode);
400	        return value >= range[0] && value <= range[1];
401	    }
