403	    /**
404	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
405	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
406	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
407	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
408	     * recognised country codes the national number (the digits after the country code) must also be
409	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
410	     * needs 10); a wrong national-number length yields {@code null}.
411	     *
412	     * @param telephone the raw telephone value (may be {@code null})
413	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
414	     *         a valid E.164 number
415	     */
416	    private String toE164(String telephone) {
417	        if (telephone == null) {
418	            return null;
419	        }
420	        String trimmed = telephone.trim();
421	        boolean hasCountryCode = trimmed.startsWith("+");
422	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
423	        if (hasCountryCode) {
424	            cleaned = cleaned.substring(1);
425	        }
426	        if (!cleaned.matches("[0-9]+")) {
427	            return null;
428	        }
429	        String digits;
430	        if (hasCountryCode) {
431	            digits = cleaned;
432	        } else {
433	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
434	            digits = "61" + national;
435	        }
436	        if (digits.length() < 8 || digits.length() > 15) {
437	            return null;
438	        }
439	        if (!hasValidNationalNumberLength(digits)) {
440	            return null;
441	        }
442	        return "+" + digits;
443	    }
444	
445	    /**
446	     * Checks the national-number length of an E.164 digit string (country code plus national
447	     * number, without the leading {@code '+'}) against its country code. When the number's country
448	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
449	     * country code must number exactly what that country requires; the longest matching country
450	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
451	     * only by the generic total-length rule).
452	     *
453	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
454	     * @return {@code true} if the national-number length is acceptable for the country code
455	     */
456	    private boolean hasValidNationalNumberLength(String digits) {
457	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
458	            .filter(entry -> digits.startsWith(entry.getKey()))
459	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
460	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
461	            .orElse(true);
462	    }
