464	    /**
465	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
466	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
467	     *
468	     * @param email the raw email value (must not be {@code null})
469	     * @return the trimmed, lower-cased email
470	     */
471	    private String normalizeEmail(String email) {
472	        return email.trim().toLowerCase(Locale.ROOT);
473	    }
