491	    /**
492	     * Applies the owner's address, preferring the structured form over the flat one. When a
493	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
494	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
495	     * non-blank {@code addressLine2} is present, by a single space and the normalized
496	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
497	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
498	     * is invalid.
499	     *
500	     * @param owner the owner whose address fields are normalized and composed in place
501	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
502	     */
503	    private boolean applyAddress(Owner owner) {
504	        String line1 = owner.getAddressLine1();
505	        if (line1 != null && !line1.isBlank()) {
506	            String normalizedLine1 = normalizeAddress(line1);
507	            owner.setAddressLine1(normalizedLine1);
508	            String composed = normalizedLine1;
509	            String line2 = owner.getAddressLine2();
510	            if (line2 != null && !line2.isBlank()) {
511	                String normalizedLine2 = normalizeAddress(line2);
512	                owner.setAddressLine2(normalizedLine2);
513	                composed = normalizedLine1 + " " + normalizedLine2;
514	            }
515	            owner.setAddress(composed);
516	            return true;
517	        }
518	        String address = normalizeAddress(owner.getAddress());
519	        if (address == null || address.isEmpty()) {
520	            return false;
521	        }
522	        owner.setAddress(address);
523	        return true;
524	    }
