526	    /**
527	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
528	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
529	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
530	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
531	     * normalized form, and every household comparison uses it.
532	     *
533	     * @param address the raw address value (may be {@code null})
534	     * @return the normalized address, or {@code null} if the input was {@code null}
535	     */
536	    private String normalizeAddress(String address) {
537	        if (address == null) {
538	            return null;
539	        }
540	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
541	        if (collapsed.isEmpty()) {
542	            return collapsed;
543	        }
544	        String[] tokens = collapsed.split(" ");
545	        StringBuilder sb = new StringBuilder(collapsed.length());
546	        for (int i = 0; i < tokens.length; i++) {
547	            if (i > 0) {
548	                sb.append(' ');
549	            }
550	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
551	        }
552	        return sb.toString();
553	    }
554	
555	    /**
556	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
557	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
558	     * so that owners are compared case-insensitively with collapsed whitespace.
559	     *
560	     * @param value the raw value (must not be {@code null})
561	     * @return the normalized comparison key
562	     */
563	    private String householdKey(String value) {
564	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
565	    }
566	
567	    /**
568	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
569	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
570	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
571	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
572	     * those two fields derives the identical identifier and therefore belongs to the same household.
573	     *
574	     * @param owner the owner whose household identifier is derived
575	     * @return the stable household identifier
576	     */
577	    private String householdId(Owner owner) {
578	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
579	        String key = householdKey(owner.getLastName()) + "|" + postcode;
580	        try {
581	            byte[] digest = MessageDigest.getInstance("SHA-256")
582	                .digest(key.getBytes(StandardCharsets.UTF_8));
583	            StringBuilder sb = new StringBuilder(digest.length * 2);
584	            for (byte b : digest) {
585	                sb.append(String.format("%02x", b));
586	            }
587	            return sb.substring(0, 12);
588	        }
589	        catch (java.security.NoSuchAlgorithmException e) {
590	            throw new IllegalStateException("SHA-256 not available", e);
591	        }
592	    }
