606	    /**
607	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
608	     * is created. It is serialized to a compact JSON object and published to the {@code AUDIT}
609	     * logger so it can be routed and asserted independently of the diagnostic log. The
610	     * {@code memberId} field carries the owner's {@link #primaryIdentifier(Owner) current primary
611	     * identifier}, the unified member id.
612	     */
613	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
614	                                     Integer membershipLevel) {
615	
616	        private static final String EVENT = "OWNER_CREATED";
617	
618	        private String toJson() {
619	            return "{\"seq\":" + this.seq
620	                + ",\"ownerId\":" + this.ownerId
621	                + ",\"memberId\":" + quote(this.memberId)
622	                + ",\"membershipLevel\":" + this.membershipLevel
623	                + ",\"event\":\"" + EVENT + "\"}";
624	        }
625	
626	        private static String quote(String value) {
627	            if (value == null) {
628	                return "null";
629	            }
630	            String escaped = value.replace("\\", "\\\\").replace("\"", "\\\"");
631	            return "\"" + escaped + "\"";
632	        }
