635	    /**
636	     * Builds the member id for a newly registered owner in the form
637	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code (the same region
638	     * derivation shared with {@link Owner#getLocality() locality}: postcode range first, falling
639	     * back to the city, or {@code 'UNKNOWN'}); {@code FY} is the 2-digit fiscal year of the
640	     * registration date (the last two digits of {@link Owner#getFiscalYear()}); {@code HASH8} is the
641	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
642	     * concatenated with the last name (the same HASH8 used by the region-and-hash identity); and
643	     * {@code CHK} is a single Luhn check digit computed over the decimal digits of
644	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). When the computed id collides with
645	     * an existing owner's member id, {@code '-<n>'} is appended using the smallest {@code n} of 2 or
646	     * more that makes the result unique, guaranteeing distinct owners always receive distinct member
647	     * ids.
648	     *
649	     * @param owner the owner whose member id is derived (with normalized telephone and registration
650	     *              date already set)
651	     * @return the assigned member id
652	     */
653	    private String memberId(Owner owner) {
654	        String region = owner.getLocality();
655	        String fiscalYear = owner.getFiscalYear();
656	        String fy = fiscalYear == null ? "00" : fiscalYear.substring(fiscalYear.length() - 2);
657	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
658	        String core = region + fy + hash8;
659	        String base = core + luhnCheckDigit(core);
660	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
661	            .map(Owner::getMemberId)
662	            .filter(id -> id != null)
663	            .collect(Collectors.toSet());
664	        if (!existingIds.contains(base)) {
665	            return base;
666	        }
667	        int n = 2;
668	        while (existingIds.contains(base + "-" + n)) {
669	            n++;
670	        }
671	        return base + "-" + n;
672	    }
673	
674	    /**
675	     * The single Luhn check digit ({@code 0}-{@code 9}) computed with the standard Luhn algorithm
676	     * over the decimal digits contained in {@code value} (non-digit characters are ignored).
677	     *
678	     * @param value the string whose decimal digits are checked
679	     * @return the Luhn check digit
680	     */
681	    private static int luhnCheckDigit(String value) {
682	        int sum = 0;
683	        boolean dbl = true;
684	        for (int i = value.length() - 1; i >= 0; i--) {
685	            char c = value.charAt(i);
686	            if (c < '0' || c > '9') {
687	                continue;
688	            }
689	            int d = c - '0';
690	            if (dbl) {
691	                d *= 2;
692	                if (d > 9) {
693	                    d -= 9;
694	                }
695	            }
696	            sum += d;
697	            dbl = !dbl;
698	        }
699	        return (10 - (sum % 10)) % 10;
700	    }
701	
702	    /**
703	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
704	     * UTF-8 bytes of {@code input}.
705	     *
706	     * @param input  the value to hash
707	     * @param length the number of leading hex characters to keep
708	     * @return the truncated, upper-cased hex digest
709	     */
710	    private String sha256UpperHex(String input, int length) {
711	        try {
712	            byte[] digest = MessageDigest.getInstance("SHA-256")
713	                .digest(input.getBytes(StandardCharsets.UTF_8));
714	            StringBuilder sb = new StringBuilder(digest.length * 2);
715	            for (byte b : digest) {
716	                sb.append(String.format("%02x", b));
717	            }
718	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
719	        }
720	        catch (java.security.NoSuchAlgorithmException e) {
721	            throw new IllegalStateException("SHA-256 not available", e);
722	        }
723	    }
724	
725	    /** Fixed public holidays that the business-day roll skips. */
726	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
727	        LocalDate.parse("2026-01-01"),
728	        LocalDate.parse("2026-01-26"),
729	        LocalDate.parse("2026-04-25"),
730	        LocalDate.parse("2026-12-25"),
731	        LocalDate.parse("2026-12-28"));
732	
733	    /**
734	     * Rolls a registration date forward onto a business day. When the given date falls on a
735	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
736	     * lands on a non-holiday weekday; a business day is returned unchanged.
737	     *
738	     * @param date the effective registration date (must not be {@code null})
739	     * @return the same date if it is already a business day, otherwise the next business day
740	     */
741	    private LocalDate toBusinessDay(LocalDate date) {
742	        while (isNonBusinessDay(date)) {
743	            date = date.plusDays(1);
744	        }
745	        return date;
746	    }
747	
748	    private boolean isNonBusinessDay(LocalDate date) {
749	        DayOfWeek dayOfWeek = date.getDayOfWeek();
750	        return dayOfWeek == DayOfWeek.SATURDAY
751	            || dayOfWeek == DayOfWeek.SUNDAY
752	            || PUBLIC_HOLIDAYS.contains(date);
753	    }
754	
755	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
756	    @Override
757	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
758	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
759	        if (currentOwner == null) {
760	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
761	        }
762	        String email = ownerFieldsDto.getEmail();
763	        if (email != null) {
764	            email = normalizeEmail(email);
765	            if (!EMAIL_PATTERN.matcher(email).matches()) {
766	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
767	            }
768	        }
769	        String telephone = toE164(ownerFieldsDto.getTelephone());
770	        if (telephone == null) {
771	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
772	        }
773	        currentOwner.setAddress(ownerFieldsDto.getAddress());
774	        currentOwner.setCity(ownerFieldsDto.getCity());
775	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
776	        currentOwner.setLastName(ownerFieldsDto.getLastName());
777	        currentOwner.setTelephone(telephone);
778	        currentOwner.setEmail(email);
779	        this.clinicService.saveOwner(currentOwner);
780	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
781	    }
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Transactional
785	    @Override
786	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
787	        Owner owner = this.clinicService.findOwnerById(ownerId);
788	        if (owner == null) {
789	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
790	        }
791	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
792	        owner.setDeleted(true);
793	        this.clinicService.saveOwner(owner);
794	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
795	    }
796	
797	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
798	    @Override
799	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
800	        Owner owner = this.clinicService.findOwnerById(ownerId);
801	        if (owner == null) {
802	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
